   86	func (d *Dispatcher) Run(ctx context.Context, interval time.Duration) {
   87		t := time.NewTicker(interval)
   88		defer t.Stop()
   89		for {
   90			select {
   91			case <-ctx.Done():
   92				return
   93			case <-d.stop:
   94				return
   95			case <-t.C:
   96				d.flush(ctx)
   97			}
   98		}
   99	}
